// Runner: launcher of the standalone executables generated by simc, a68c and the IDE.
// A generated .exe = copy of Runner.exe (single file) + compiled program appended at the end
// (Studio.Common.ExePackage format).

using System.Text;
using Studio.Common;
using Studio.Tooling;

namespace Studio.Runner;

static class Program
{
    static int Main(string[] args)
    {
        try { Console.OutputEncoding = new UTF8Encoding(false); } catch { }

        var exePath = Environment.ProcessPath;
        (string LanguageId, byte[] Payload)? package = null;
        try
        {
            if (exePath != null) package = ExePackage.Read(exePath);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"cannot read the embedded program: {ex.Message}");
            return 3;
        }

        if (package == null)
        {
            PrintUsage();
            return args.Length > 0 && (args[0] is "-h" or "--help" or "/?") ? 0 : 2;
        }

        var (langId, payload) = package.Value;
        var language = LanguageRegistry.FindById(langId);
        if (language == null)
        {
            Console.Error.WriteLine($"unknown language in executable: '{langId}'");
            return 3;
        }

        ICompiledProgram program;
        try
        {
            program = language.Deserialize(payload);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"embedded {language.DisplayName} program is unreadable: {ex.Message}");
            return 3;
        }

        var workDir = Environment.CurrentDirectory;
        return ProgramHost.RunInConsole(program, workDir);
    }

    static void PrintUsage()
    {
        Console.WriteLine("Runner — Simula 67 / Algol 68 program launcher");
        Console.WriteLine();
        Console.WriteLine("This file contains no program. It is the base of the standalone executables");
        Console.WriteLine("produced by the compilers:");
        Console.WriteLine("  simc program.sim -o program.exe");
        Console.WriteLine("  a68c program.a68 -o program.exe");
        Console.WriteLine("or by the 'Generate standalone .exe' command of Simula 67 & Algol 68 Studio.");
    }
}
